1|import { describe, it } from "node:test";
2|import assert from "node:assert/strict";
3|import { createRunnerClient, isTransientBackendError } from "./client.js";
4|
5|/***
6| * MARK: backend-outage tests
7| * @description Regression suite for S4 (transient backend errors are
8| *   non-fatal to the runner): the `isTransientBackendError` classifier
9| *   boundary (GUIDE-04 section 3, flipped red — transient returns,
10| *   stale-epoch/auth/unknown stay fatal) and the outage wire shapes
11| *   through the real client call path (GUIDE-04 section 2 — 502 shape,
12| *   dropped-socket shape, recovery).
13| * @example run `node --test runner/client.backendOutage.test.js`
14| ***/
15|
16|function stubFetch(handler) {
17|	const calls = [];
18|	const fetchImpl = async (url, opts) => {
19|		calls.push({ url, opts });
20|		return handler(url, opts, calls);
21|	};
22|	return { fetchImpl, calls };
23|}
24|
25|const ok = (data) => ({ ok: true, status: 200, json: async () => data });
26|const fail = (status, data) => ({ ok: false, status, json: async () => data });
27|// Proxy-restart shape: a gateway 502 usually carries an HTML body, so
28|// `res.json()` rejects and the client reports `{ statusCode: 502, code: null }`.
29|const failHtml = (status) => ({
30|	ok: false,
31|	status,
32|	json: async () => {
33|		throw new Error("Unexpected token '<'");
34|	},
35|});
36|const httpError = (status, code = null, message = `Backend ${status}`) =>
37|	Object.assign(new Error(message), { statusCode: status, code });
38|// Undici fetch-failure shape (observed on Node 24): `TypeError: fetch
39|// failed` with the system error nested under `cause`.
40|const socketError = (code, message = "fetch failed") =>
41|	Object.assign(new TypeError(message), { cause: Object.assign(new Error(code), { code }) });
42|
43|describe("isTransientBackendError", () => {
44|	it("matches gateway outages with and without a backend code", () => {
45|		for (const status of [502, 503, 504]) {
46|			assert.equal(isTransientBackendError(httpError(status)), true, `status ${status}`);
47|			assert.equal(isTransientBackendError(httpError(status, "SOME_CODE")), true, `status ${status} + code`);
48|		}
49|		// A real backend shape: the integration queue answers 503 with a
50|		// semantic code when unavailable — still a gateway outage.
51|		assert.equal(isTransientBackendError(httpError(503, "NO_INTEGRATION_QUEUE")), true);
52|	});
53|
54|	it("matches dropped-socket and network-layer failures by stable codes", () => {
55|		for (const code of [
56|			"ECONNREFUSED",
57|			"ECONNRESET",
58|			"ETIMEDOUT",
59|			"EAI_AGAIN",
60|			"ENOTFOUND",
61|			"EPIPE",
62|			"EHOSTUNREACH",
63|			"ENETUNREACH",
64|			"UND_ERR_SOCKET",
65|			"UND_ERR_CONNECT_TIMEOUT",
66|			"UND_ERR_HEADERS_TIMEOUT",
67|			"UND_ERR_BODY_TIMEOUT",
68|		]) {
69|			assert.equal(isTransientBackendError(socketError(code)), true, `cause ${code}`);
70|			assert.equal(
71|				isTransientBackendError(Object.assign(new Error(code), { code })),
72|				true,
73|				`direct ${code}`,
74|			);
75|		}
76|		// The system code may nest deeper than one cause level.
77|		const nested = new TypeError("fetch failed");
78|		nested.cause = new Error("outer");
79|		nested.cause.cause = Object.assign(new Error("ECONNRESET"), { code: "ECONNRESET" });
80|		assert.equal(isTransientBackendError(nested), true);
81|	});
82|
83|	it("keeps STALE_EPOCH, auth failures, and other statuses fatal", () => {
84|		assert.equal(isTransientBackendError(httpError(409, "STALE_EPOCH", "Stale")), false);
85|		assert.equal(isTransientBackendError(httpError(401, "INVALID_CREDENTIAL", "Unknown credential")), false);
86|		assert.equal(isTransientBackendError(httpError(403, "RUNNER_REVOKED", "Revoked")), false);
87|		assert.equal(isTransientBackendError(httpError(429, "FLEET_CONCURRENCY_EXHAUSTED", "Busy")), false);
88|		// A 500 is a backend bug, not an outage: it stays loud.
89|		assert.equal(isTransientBackendError(httpError(500, null, "Backend 500")), false);
90|		assert.equal(isTransientBackendError(httpError(404, null, "Not found")), false);
91|	});
92|
93|	it("keeps unknown and ambiguous errors fatal (never an inverted catch-all)", () => {
94|		assert.equal(isTransientBackendError(new Error("boom")), false);
95|		assert.equal(
96|			isTransientBackendError(Object.assign(new Error("cap"), { code: "WORKTREE_CAP_REACHED" })),
97|			false,
98|		);
99|		// Bare `fetch failed` with no recognized code (e.g. a
100|		// misconfigured backendUrl) stays loud — ambiguous failures
101|		// must not spin the loop forever.
102|		assert.equal(isTransientBackendError(new TypeError("fetch failed")), false);
103|		const unrecognized = new TypeError("fetch failed");
104|		unrecognized.cause = new Error("bad port");
105|		assert.equal(isTransientBackendError(unrecognized), false);
106|		assert.equal(isTransientBackendError(null), false);
107|		assert.equal(isTransientBackendError(undefined), false);
108|		assert.equal(isTransientBackendError("502"), false);
109|		assert.equal(isTransientBackendError(502), false);
110|	});
111|});
112|
113|describe("backend outage shapes through the client", () => {
114|	it("a 502 surfaces as a transient error (json and proxy-html bodies)", async () => {
115|		for (const res of [fail(502, { error: "Bad Gateway", code: null }), failHtml(502)]) {
116|			const { fetchImpl } = stubFetch(() => res);
117|			const client = createRunnerClient({ backendUrl: "http://x:3100", fetchImpl });
118|			const err = await client.dispatchClaim({}).then(
119|				() => null,
120|				(e) => e,
121|			);
122|			assert.ok(err, "expected dispatchClaim to reject");
123|			assert.equal(err.statusCode, 502);
124|			assert.equal(isTransientBackendError(err), true);
125|		}
126|	});
127|
128|	it("503 and 504 surface as transient errors", async () => {
129|		for (const status of [503, 504]) {
130|			const { fetchImpl } = stubFetch(() => fail(status, { error: "Down", code: null }));
131|			const client = createRunnerClient({ backendUrl: "http://x:3100", fetchImpl });
132|			const err = await client.heartbeat({ runnerId: "r1", facts: {} }).then(
133|				() => null,
134|				(e) => e,
135|			);
136|			assert.ok(err, `expected heartbeat to reject on ${status}`);
137|			assert.equal(isTransientBackendError(err), true);
138|		}
139|	});
140|
141|	it("a dropped socket surfaces as a transient error", async () => {
142|		for (const code of ["ECONNREFUSED", "UND_ERR_SOCKET", "ECONNRESET"]) {
143|			const { fetchImpl } = stubFetch(async () => {
144|				throw socketError(code);
145|			});
146|			const client = createRunnerClient({ backendUrl: "http://x:3100", fetchImpl });
147|			const err = await client.dispatchClaim({}).then(
148|				() => null,
149|				(e) => e,
150|			);
151|			assert.ok(err, `expected dispatchClaim to reject on ${code}`);
152|			assert.equal(err.statusCode, undefined);
153|			assert.equal(isTransientBackendError(err), true);
154|		}
155|	});
156|
157|	it("recovers after an outage: no wedged state once the backend answers", async () => {
158|		let n = 0;
159|		const { fetchImpl, calls } = stubFetch(async () => {
160|			n += 1;
161|			if (n === 1) return failHtml(502);
162|			if (n === 2) throw socketError("ECONNREFUSED");
163|			return ok({ assigned: false, code: "NO_CLAIMABLE_TASKS" });
164|		});
165|		const client = createRunnerClient({ backendUrl: "http://x:3100", fetchImpl });
166|		const first = await client.dispatchClaim({}).then(
167|			() => null,
168|			(e) => e,
169|		);
170|		assert.ok(first && isTransientBackendError(first));
171|		const second = await client.dispatchClaim({}).then(
172|			() => null,
173|			(e) => e,
174|		);
175|		assert.ok(second && isTransientBackendError(second));
176|		const third = await client.dispatchClaim({});
177|		assert.deepEqual(third, { assigned: false, code: "NO_CLAIMABLE_TASKS" });
178|		assert.equal(calls.length, 3);
179|	});
180|});

