1|/***
2| * MARK: createRunnerClient
3| * @description Thin fetch wrapper over the Runner-facing backend API
4| *   (ADR 0009). Holds the per-Runner credential after approval and sends
5| *   it as `x-runner-credential`; every call throws the backend's
6| *   `{ error, code }` shape on non-2xx so the daemon can branch on codes.
7| * @example const client = createRunnerClient({ backendUrl: 'http://localhost:3100' })
8| * @param {Object} opts - Options.
9| * @param {string} opts.backendUrl - Backend origin (no trailing slash).
10| * @param {Function} [opts.fetchImpl] - Fetch implementation (tests inject a stub).
11| * @returns {Object} Runner API client.
12| ***/
13|/***
14| * MARK: isTransientBackendError
15| * @description Explicit non-fatal set for backend outages (S4): HTTP
16| *   502/503/504 (the backend or its proxy is restarting) plus
17| *   network-layer fetch rejections where the backend never answered
18| *   (refused/reset connection, timeout, DNS failure, dropped socket —
19| *   matched on stable `code`/`cause.code` signals, never message text).
20| *   Everything else returns false — STALE_EPOCH, auth rejections (401
21| *   INVALID_CREDENTIAL, 403), 429, 500, and unknown errors stay fatal
22| *   by construction, so new failure modes stay loud. Pure predicate:
23| *   no logging, no dependencies.
24| * @example isTransientBackendError(Object.assign(new Error('x'), { statusCode: 502 })) => true
25| * @param {*} err - Thrown value from a backend call.
26| * @returns {boolean} True only for the enumerated transient set.
27| ***/
28|const TRANSIENT_BACKEND_STATUSES = new Set([502, 503, 504]);
29|// Node system codes (ECONN*) plus undici fetch-failure codes (UND_ERR_*,
30|// e.g. a destroyed socket surfaces as UND_ERR_SOCKET on Node 20/22/24).
31|// Deliberately NOT matched: bare `TypeError: fetch failed` with no
32|// recognized code (e.g. a misconfigured backendUrl) — ambiguous failures
33|// stay loud rather than spinning the loop forever.
34|const TRANSIENT_NETWORK_CODES = new Set([
35|	"ECONNREFUSED",
36|	"ECONNRESET",
37|	"ETIMEDOUT",
38|	"EAI_AGAIN",
39|	"ENOTFOUND",
40|	"EPIPE",
41|	"EHOSTUNREACH",
42|	"ENETUNREACH",
43|	"ENETDOWN",
44|	"UND_ERR_SOCKET",
45|	"UND_ERR_CONNECT_TIMEOUT",
46|	"UND_ERR_HEADERS_TIMEOUT",
47|	"UND_ERR_BODY_TIMEOUT",
48|]);
49|
50|export function isTransientBackendError(err) {
51|	if (!err || (typeof err !== "object" && typeof err !== "function")) return false;
52|	// A status means the backend answered: only gateway outages are
53|	// transient — 401/403/409/429/500 and friends stay fatal/loud.
54|	const status = Number(err.statusCode);
55|	if (Number.isFinite(status)) return TRANSIENT_BACKEND_STATUSES.has(status);
56|	// No status: fetchImpl itself rejected. Walk the cause chain (undici
57|	// nests the system error under `cause`) for a recognized code.
58|	let current = err;
59|	for (let depth = 0; depth < 4 && current && (typeof current === "object" || typeof current === "function"); depth += 1) {
60|		if (typeof current.code === "string" && TRANSIENT_NETWORK_CODES.has(current.code)) return true;
61|		current = current.cause;
62|	}
63|	return false;
64|}
65|
66|export function createRunnerClient({ backendUrl, fetchImpl = fetch }) {
67|	const base = String(backendUrl).replace(/\/+$/, "");
68|	let credential = "";
69|
70|	async function call(path, { method = "GET", body, credential: [REDACTED] } = {}) {
71|		const cred = override ?? credential;
72|		const res = await fetchImpl(`${base}${path}`, {
73|			method,
74|			headers: {
75|				...(body !== undefined ? { "content-type": "application/json" } : {}),
76|				...(cred ? { "x-runner-credential": cred } : {}),
77|			},
78|			body: body !== undefined ? JSON.stringify(body) : undefined,
79|		});
80|		let data = null;
81|		try {
82|			data = await res.json();
83|		} catch {
84|			data = null;
85|		}
86|		if (!res.ok) {
87|			const err = new Error(data?.error || `Backend ${res.status} on ${path}`);
88|			err.statusCode = res.status;
89|			err.code = data?.code ?? null;
90|			throw err;
91|		}
92|		return data;
93|	}
94|
95|	return {
96|		setCredential(next) {
97|			credential = next;
98|		},
99|		register({ runnerId, joinToken, facts, joinNonce }) {
100|			return call("/runners/register", {
101|				method: "POST",
102|				body: { runnerId, joinToken, facts, joinNonce },
103|			});
104|		},
105|		heartbeat({ runnerId, facts }) {
106|			return call("/runners/heartbeat", {
107|				method: "POST",
108|				body: { runnerId, facts },
109|			});
