32|const ROOTS = ["api", "shared", path.join("frontend", "src")];
33|const SOURCE_EXTS = new Set([".js", ".jsx"]);
34|const SKIP_PARTS = new Set(["node_modules", "dist", ".git", "coverage", "build", "__fixtures__", "__mocks__"]);
