36|/***
37| * MARK: isDocSourceFile
38| * @description Whether a repo-relative POSIX path is in the `@example` gate's
39| *   scope: a .js/.jsx file under api/, shared/, or frontend/src/, excluding
40| *   test/spec files, fixtures, mocks, and build output.
41| * @example isDocSourceFile("api/work/taskErrors.js") => true
42| * @param {string} relPath - Repo-relative POSIX path.
43| * @returns {boolean} True when the file is checked by this gate.
44| ***/
45|export function isDocSourceFile(relPath) {
46|	const ext = path.posix.extname(relPath);
47|	if (!SOURCE_EXTS.has(ext)) return false;
48|	if (!ROOTS.some((root) => relPath === root || relPath.startsWith(`${root}/`)))
49|		return false;
50|	const base = path.posix.basename(relPath);
51|	if (base.includes(".test.") || base.includes(".spec.")) return false;
52|	if (base.includes(".fixtures.") || base.includes(".fixture.")) return false;
53|	if (base.includes("__fixtures__") || base.includes("__mocks__")) return false;
54|	if (relPath.split("/").some((part) => SKIP_PARTS.has(part))) return false;
55|	return true;
