190| * @param {string} jsdoc - JSDoc block text.
191| * @returns {boolean} True when an @example tag is present.
192| ***/
193|export function hasExampleTag(jsdoc) {
194|	return /(^|\s)@example(\s|$)/.test(jsdoc);
195|}
