197|/***
198| * MARK: findPublicExports
199| * @description Lists every public export declared in a source file: `export
200| *   function/async function/class/const/let/var` (each declared name) and
201| *   `export default ...` (name "default"). Re-export lists (`export { a }`,
202| *   `export * from`) declare nothing new and are skipped. Each entry records
203| *   whether its nearest preceding JSDoc block carries `@example`.
204| * @example findPublicExports("export function f() {}") => [{ exportName: "f", kind: "function", hasExample: false }]
205| * @param {string} source - Raw file text.
206| * @returns {Array<{exportName: string, kind: string, hasExample: boolean}>} Declared exports in source order.
207| ***/
208|export function findPublicExports(source) {
209|	const masked = maskNonCode(source);
210|	const found = [];
211|	const len = masked.length;
212|	const isIdChar = (c) => /[$\w]/.test(c || "");
213|	const isIdStart = (c) => /[$A-Za-z_]/.test(c || "");
214|	const skipWs = (j) => {
215|		while (j < len && /\s/.test(masked[j])) j++;
216|		return j;
217|	};
218|	const readIdent = (j) => {
219|		let name = "";
220|		if (!isIdStart(masked[j])) return { name: "", next: j };
221|		while (j < len && isIdChar(masked[j])) {
222|			name += masked[j];
223|			j++;
224|		}
225|		return { name, next: j };
226|	};
227|	const keywordAt = (word, i) =>
228|		masked.startsWith(word, i) &&
229|		!isIdChar(masked[i - 1]) &&
230|		!isIdChar(masked[i + word.length]);
231|
232|	let i = 0;
233|	while (i < len) {
234|		if (keywordAt("export", i)) {
235|			let j = skipWs(i + 6);
236|			if (keywordAt("default", j)) {
237|				let k = skipWs(j + 7);
238|				let kind = "default";
239|				if (keywordAt("function", k)) kind = "function";
240|				else if (keywordAt("class", k)) kind = "class";
241|				found.push({
242|					exportName: "default",
243|					kind,
244|					hasExample: checkExample(source, i),
245|				});
246|				i = j + 7;
247|				continue;
248|			}
249|			if (keywordAt("async", j)) {
250|				const after = skipWs(j + 5);
251|				if (keywordAt("function", after)) j = after;
252|			}
253|			if (keywordAt("function", j)) {
254|				let k = skipWs(j + 8);
255|				if (masked[k] === "*") k = skipWs(k + 1);
256|				const { name } = readIdent(k);
257|				found.push({
258|					exportName: name || "default",
259|					kind: "function",
260|					hasExample: checkExample(source, i),
261|				});
262|				i = k;
263|				continue;
264|			}
265|			if (keywordAt("class", j)) {
266|				let k = skipWs(j + 5);
267|				const { name } = readIdent(k);
268|				found.push({
269|					exportName: name || "default",
270|					kind: "class",
271|					hasExample: checkExample(source, i),
272|				});
273|				i = k;
274|				continue;
275|			}
276|			if (
277|				keywordAt("const", j) ||
278|				keywordAt("let", j) ||
279|				keywordAt("var", j)
280|			) {
281|				const kind = masked.slice(j, j + 5) === "const" ? "const" : keywordAt("let", j) ? "let" : "var";
282|				let k = skipWs(j + kind.length);
283|				// One JSDoc block heads the whole declaration statement.
284|				const statementHasExample = checkExample(source, i);
285|				// Walk comma-separated declarators at this level only.
286|				let depth = 0;
287|				let expectName = true;
288|				while (k < len) {
289|					const ch = masked[k];
290|					if (ch === "(" || ch === "[" || ch === "{") depth++;
291|					else if (ch === ")" || ch === "]" || ch === "}") depth--;
292|					else if (ch === ";" && depth <= 0) break;
293|					else if (ch === "," && depth === 0) {
294|						expectName = true;
295|						k++;
296|						k = skipWs(k);
297|						continue;
298|					}
299|					if (expectName && depth === 0) {
300|						k = skipWs(k);
301|						const { name, next } = readIdent(k);
302|						if (name) {
303|							found.push({ exportName: name, kind, hasExample: statementHasExample });
304|							k = next;
305|							expectName = false;
306|							continue;
307|						}
308|						expectName = false;
309|					}
310|					k++;
311|				}
312|				i = k;
313|				continue;
314|			}
315|			// export { ... } / export * from ... : no new declaration — skip.
316|			i = j;
317|			continue;
318|		}
319|		i++;
320|	}
321|	return found;
322|}
323|
324|function checkExample(source, exportIndex) {
325|	const jsdoc = nearestJsdoc(source, exportIndex);
326|	return jsdoc !== null && hasExampleTag(jsdoc);
327|}
