329|/***
330| * MARK: collectDocSourceFiles
331| * @description Walks the gate's roots and returns every in-scope source file
332| *   as a repo-relative POSIX path, sorted.
333| * @example collectDocSourceFiles().every(isDocSourceFile) => true
334| * @returns {Array<string>} Sorted repo-relative POSIX paths.
335| ***/
336|export function collectDocSourceFiles() {
337|	const found = [];
338|	const walk = (dir) => {
339|		for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
340|			if (entry.name.startsWith(".") || SKIP_PARTS.has(entry.name)) continue;
341|			const full = path.join(dir, entry.name);
342|			if (entry.isDirectory()) walk(full);
343|			else if (entry.isFile()) {
344|				const rel = path.relative(REPO_ROOT, full).split(path.sep).join("/");
345|				if (isDocSourceFile(rel)) found.push(rel);
346|			}
347|		}
348|	};
349|	for (const root of ROOTS) {
350|		const abs = path.join(REPO_ROOT, root);
351|		if (fs.existsSync(abs)) walk(abs);
352|	}
353|	return found.sort();
354|}
