356|/***
357| * MARK: scanAllExports
358| * @description Scans the tree and returns every public export with its
359| *   `@example` status.
360| * @example scanAllExports().total counts every declared export
361| * @returns {{ total: number, missing: Array<{file: string, exportName: string, kind: string}> }} Full scan.
362| ***/
363|export function scanAllExports() {
364|	let total = 0;
365|	const missing = [];
366|	for (const file of collectDocSourceFiles()) {
367|		const source = fs.readFileSync(path.join(REPO_ROOT, file), "utf8");
368|		for (const exp of findPublicExports(source)) {
369|			total++;
370|			if (!exp.hasExample) {
371|				missing.push({ file, exportName: exp.exportName, kind: exp.kind });
