373|		}
374|	}
375|	missing.sort((a, b) =>
376|		a.file.localeCompare(b.file) ||
377|		a.exportName.localeCompare(b.exportName) ||
378|		a.kind.localeCompare(b.kind),
379|	);
380|	return { total, missing };
381|}
382|
383|/***
384| * MARK: scanMissing
385| * @description Scans the tree and returns every public export missing
386| *   `@example`, keyed as { file, exportName, kind }.
387| * @example scanMissing() returns an array of { file, exportName, kind }
388| * @returns {Array<{file: string, exportName: string, kind: string}>} Missing exports, sorted.
389| ***/
390|export function scanMissing() {
