394|/***
395| * MARK: readBaseline
396| * @description Reads the committed missing-`@example` baseline (empty when
397| *   absent — a missing file means "no grandfathered gap", never a crash).
398| * @example readBaseline() returns an array of { file, exportName, kind }
399| * @returns {Array<{file: string, exportName: string, kind: string}>} Baselined entries.
400| ***/
401|export function readBaseline() {
402|	try {
403|		const raw = JSON.parse(fs.readFileSync(BASELINE_PATH, "utf8"));
404|		return Array.isArray(raw) ? raw : [];
405|	} catch {
406|		return [];
407|	}
408|}
