410|const keyOf = (entry) => `${entry.file}::${entry.exportName}::${entry.kind}`;
411|
412|/***
413| * MARK: checkMissing
414| * @description Pure gate core: missing exports still present in the baseline
415| *   keep passing (the gap stays a to-do per q6); anything else fails. In
416| *   strict mode the baseline is ignored and every missing export fails.
417| * @example checkMissing([{...}], [{...}], false) splits new vs grandfathered
418| * @param {Array<Object>} missing - Currently-missing exports.
419| * @param {Array<Object>} baseline - Grandfathered missing exports.
420| * @param {boolean} strict - Fail on every missing export.
421| * @returns {{ failures: Array<Object>, prunable: Array<Object> }} New failures and baseline entries that now have @example.
422| ***/
423|export function checkMissing(missing, baseline, strict = false) {
424|	const baselined = new Set(baseline.map(keyOf));
425|	const failures = strict
426|		? [...missing]
427|		: missing.filter((entry) => !baselined.has(keyOf(entry)));
428|	const present = new Set(missing.map(keyOf));
429|	const prunable = baseline.filter((entry) => !present.has(keyOf(entry)));
430|	return { failures, prunable };
