66|export function maskNonCode(source) {
67|	const chars = source.split("");
68|	const len = source.length;
69|	const mask = (from, to) => {
70|		for (let k = from; k < to; k++) {
71|			if (chars[k] !== "\n") chars[k] = " ";
72|		}
73|	};
74|	const skipString = (i) => {
75|		const quote = source[i];
76|		let j = i + 1;
77|		while (j < len) {
78|			if (source[j] === "\\") j += 2;
79|			else if (source[j] === quote) {
80|				j++;
81|				break;
82|			} else j++;
83|		}
84|		mask(i, j);
