86|	};
87|	// Skips `${ ... }` starting at the `$`, honouring nested strings,
88|	// comments, templates, and braces. Returns the index after the `}`.
89|	const skipInterpolation = (i) => {
90|		let j = i + 2;
91|		let depth = 1;
92|		while (j < len && depth > 0) {
93|			const ch = source[j];
94|			const next = source[j + 1];
95|			if (ch === "/" && next === "/") {
96|				let k = j + 2;
97|				while (k < len && source[k] !== "\n") k++;
98|				mask(j, k);
99|				j = k;
100|			} else if (ch === "/" && next === "*") {
101|				const end = source.indexOf("*/", j + 2);
102|				const k = end === -1 ? len : end + 2;
103|				mask(j, k);
104|				j = k;
105|			} else if (ch === "'" || ch === '"') {
106|				j = skipString(j);
107|			} else if (ch === "`") {
108|				j = skipTemplate(j);
109|			} else {
110|				if (ch === "{") depth++;
111|				else if (ch === "}") depth--;
112|				j++;
113|			}
114|		}
115|		return j;
116|	};
117|	// Masks a template literal starting at the backtick, scanning
118|	// `${}` interpolations as code. Returns the index after the closing
119|	// backtick (or end of input for an unterminated literal).
120|	const skipTemplate = (i) => {
121|		let j = i + 1;
122|		let segStart = j;
123|		while (j < len) {
124|			const ch = source[j];
125|			if (ch === "\\") j += 2;
126|			else if (ch === "`") {
127|				mask(segStart, j);
128|				mask(j, j + 1);
129|				return j + 1;
130|			} else if (ch === "$" && source[j + 1] === "{") {
131|				mask(segStart, j);
132|				j = skipInterpolation(j);
133|				segStart = j;
134|			} else j++;
135|		}
136|		if (segStart < len) mask(segStart, len);
137|		return len;
138|	};
139|	let i = 0;
140|	while (i < len) {
141|		const ch = source[i];
142|		const next = source[i + 1];
143|		if (ch === "/" && next === "/") {
144|			let j = i + 2;
145|			while (j < len && source[j] !== "\n") j++;
146|			mask(i, j);
147|			i = j;
148|		} else if (ch === "/" && next === "*") {
149|			const end = source.indexOf("*/", i + 2);
150|			const j = end === -1 ? len : end + 2;
151|			mask(i, j);
152|			i = j;
153|		} else if (ch === "'" || ch === '"') {
154|			i = skipString(i);
155|		} else if (ch === "`") {
156|			i = skipTemplate(i);
157|		} else {
