1|const TRANSIENT_BACKEND_STATUSES = new Set([502, 503, 504]);
2|// Node system codes (ECONN*) plus undici fetch-failure codes (UND_ERR_*,
3|// e.g. a destroyed socket surfaces as UND_ERR_SOCKET on Node 20/22/24).
